    $commitPayload=['mode'=>'commitment','request_key'=>bin2hex(random_bytes(16)),'budget_request_id'=>$reviewed['id'],'budget_item_id'=>$reviewed['items'][0]['id'],'amount'=>'1500'];$commit=ac_budget_realize($conn,$finance,$commitPayload);check(budget_read($conn,(int)$reviewed['id'])['remaining_amount']==='2500.00','Commitment reserves budget without accrual');ac_budget_realize($conn,$finance,array_merge($commitPayload,['mode'=>'cancel_commitment','commitment_id'=>$commit['commitment_id'],'request_key'=>bin2hex(random_bytes(16))]));check(budget_read($conn,(int)$reviewed['id'])['remaining_amount']==='4000.00','Cancellation releases only open commitment');ac_budget_realize($conn,$admin,['mode'=>'close','request_key'=>bin2hex(random_bytes(16)),'budget_request_id'=>$reviewed['id'],'note'=>'Kebutuhan tidak dilanjutkan']);check(budget_read($conn,(int)$reviewed['id'])['status']==='closed','Reviewer can close budget without financial entry');
    $coverage=ac_reports($conn,[])['coverage'];check($coverage['complete']===false&&$coverage['opening_balances_verified']===null,'Reports do not certify unverified opening balances');
    require __DIR__.'/accounting_http_checks.php';accounting_http_checks($conn,$testName,$payload);
    echo "PASS: $checks accounting integration checks.\n";
}finally{$conn->select_db($original);$conn->query("DROP DATABASE `$testName`");}
